package app.kivo.store;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import org.json.*;
/** Completion notifications open Kivo for verification, never an APK installer directly. */
public class DownloadCompleteReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context context,Intent intent){if(!DownloadManager.ACTION_DOWNLOAD_COMPLETE.equals(intent.getAction()))return;long id=intent.getLongExtra(DownloadManager.EXTRA_DOWNLOAD_ID,-1);boolean ours=false;try{JSONArray list=new JSONArray(context.getSharedPreferences("kivo",0).getString("systemDownloads","[]"));for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optLong("id")==id)ours=true;}catch(Exception ignored){}if(!ours)return;try(android.database.Cursor c=((DownloadManager)context.getSystemService(Context.DOWNLOAD_SERVICE)).query(new DownloadManager.Query().setFilterById(id))){if(c==null||!c.moveToFirst())return;int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status!=DownloadManager.STATUS_SUCCESSFUL&&status!=DownloadManager.STATUS_FAILED)return;}catch(Exception e){return;}if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("downloads","Descargas de Kivo",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(context,MainActivity.class).putExtra("showDownloads",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(context,(int)id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(context,"downloads").setSmallIcon(android.R.drawable.stat_sys_download_done).setContentTitle("Tu descarga de Kivo terminó").setContentText("Abre Kivo para comprobar el archivo y continuar.").setContentIntent(action).setAutoCancel(true).build();try{manager.notify((int)id,n);}catch(SecurityException ignored){}}
}
